39	/// Generates an entry point for a web target.
40	// Keep this in sync with build_runner/resident_web_runner.dart
41	class WebEntrypointTarget extends Target {
42	  const WebEntrypointTarget();
43	
44	  @override
45	  String get name => 'web_entrypoint';
46	
47	  @override
48	  List<Target> get dependencies => const <Target>[];
49	
50	  @override
51	  List<Source> get inputs => const <Source>[
52	    Source.pattern('{FLUTTER_ROOT}/packages/flutter_tools/lib/src/build_system/targets/web.dart'),
53	  ];
54	
55	  @override
56	  List<Source> get outputs => const <Source>[Source.pattern('{BUILD_DIR}/main.dart')];
57	
58	  @override
59	  Future<void> build(Environment environment) async {
60	    final String? targetFile = environment.defines[kTargetFile];
61	    final Uri importUri = environment.fileSystem.file(targetFile).absolute.uri;
62	    final File packageConfigFile = findPackageConfigFileOrDefault(environment.projectDir);
63	
64	    final PackageConfig packageConfig = await loadPackageConfigWithLogging(
65	      packageConfigFile,
66	      logger: environment.logger,
67	    );
68	    final FlutterProject flutterProject = FlutterProject.current();
69	    final LanguageVersion languageVersion = determineLanguageVersion(
70	      environment.fileSystem.file(targetFile),
71	      packageConfig[flutterProject.manifest.appName],
72	      Cache.flutterRoot!,
73	    );
74	
75	    // Use the PackageConfig to find the correct package-scheme import path
76	    // for the user application. If the application has a mix of package-scheme
77	    // and relative imports for a library, then importing the entrypoint as a
78	    // file-scheme will cause said library to be recognized as two distinct
79	    // libraries. This can cause surprising behavior as types from that library
80	    // will be considered distinct from each other.
81	    //
82	    // By construction, this will only be null if the package_config.json file
83	    // does not have an entry for the user's application or if the main file is
84	    // outside of the lib/ directory.
85	    final String importedEntrypoint =
86	        packageConfig.toPackageUri(importUri)?.toString() ?? importUri.toString();
87	
88	    await injectBuildTimePluginFilesForWebPlatform(
89	      flutterProject,
90	      destination: environment.buildDir,
91	    );
92	    // The below works because `injectBuildTimePluginFiles` is configured to write
93	    // the web_plugin_registrant.dart file alongside the generated main.dart
94	    const generatedImport = 'web_plugin_registrant.dart';
95	
96	    final String contents = main_dart.generateMainDartFile(
97	      importedEntrypoint,
98	      languageVersion: languageVersion,
99	      pluginRegistrantEntrypoint: generatedImport,
100	    );
101	
102	    environment.buildDir.childFile('main.dart').writeAsStringSync(contents);
103	  }
104	}
